755	/**
756	 * The holidays on a sheet, earliest first; no date is on it twice. A claim's due-by, when it is fixed as the
757	 * claim is added, is moved past the holidays on the sheet then (see {@link #pastHolidays}); a holiday added
758	 * later leaves the due-by dates already fixed as they are.
759	 */
760	@Service
761	public class HolidayService {
762	
763	    private final HolidayRepository holidays;
764	    private final SheetService sheets;
765	    private final SheetRepository sheetRows;
766	    private final ApplicationEventPublisher events;
767	
768	    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows,
769	            ApplicationEventPublisher events) {
770	        this.holidays = holidays;
771	        this.sheets = sheets;
772	        this.sheetRows = sheetRows;
773	        this.events = events;
774	    }
775	
776	    @Transactional(readOnly = true)
777	    public List<Holiday> list(String sheetId) {
778	        return holidays.findBySheetIdOrderByDayAsc(sheetId);
779	    }
780	
781	    /** Add a holiday; refused when the date is already on the sheet's list. */
782	    @Transactional
783	    public Holiday add(String sheetId, String user, LocalDate date) {
784	        sheets.load(sheetId, user);
785	        sheetRows.lockById(sheetId);
786	        if (holidays.existsBySheetIdAndDay(sheetId, date)) {
787	            throw new HolidayRefused("That date is already a holiday on this sheet.");
788	        }
789	        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
790	        events.publishEvent(new HolidayAdded(sheetId, user, date));
791	        return saved;
792	    }
793	
794	    /** The date, or when it is a holiday on the sheet, the next day after it that is not. */
795	    @Transactional(readOnly = true)
796	    public LocalDate pastHolidays(String sheetId, LocalDate date) {
797	        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDay).collect(Collectors.toSet());
798	        LocalDate day = date;
799	        while (days.contains(day)) {
800	            day = day.plusDays(1);
801	        }
802	        return day;
803	    }
804	}
